//! The showcase level, as it actually ships: read off disk and walked.
//!
//! ```text
//!   assets/scenes/showcase.json ──► the loader ──► collision ──► a character walking
//! ```
//!
//! Every other test in this repository builds its level in memory. This one reads the file,
//! because the file is what the game loads and what an author opens in the editor, and a level
//! that is correct in a builder function and broken on disk is broken. It is regenerated by
//! `cargo run -p engine-assetgen --bin level_gen`, so if this test starts failing the fix is
//! usually to run that.
//!
//! What it checks is the thing the phases were for: that terrain, cliffs, an overhang, caves,
//! water and a spawn point are all in one level at once, and that a player can walk through it.

#![allow(
    clippy::expect_used,
    reason = "test code may assert on known-good values"
)]

use engine_collision::controller::{CharacterConfig, CharacterState, move_character};
use engine_collision::world::{CollisionWorld, QueryBuffers};
use engine_core::math::Vec3;
use engine_environment::EnvironmentScene;

/// The level, read from the repository's own assets directory.
fn showcase() -> EnvironmentScene {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../assets/scenes/showcase.json"
    );
    engine_environment::scene_file::load(path).expect(
        "assets/scenes/showcase.json loads; regenerate it with \
         `cargo run -p engine-assetgen --bin level_gen`",
    )
}

fn world_of(scene: &EnvironmentScene) -> CollisionWorld {
    let mut world = CollisionWorld::new();
    world.add_ground(scene.ground_height, "FLOOR");
    engine_game::arena::add_terrain_collision(&mut world, scene);
    engine_game::arena::add_environment_collision(&mut world, scene);
    world.rebuild_broad_phase();
    world
}

/// Walks a character from `from` towards `to` and reports where it ended up.
fn walk(world: &CollisionWorld, from: Vec3, to: Vec3) -> Vec3 {
    let config = CharacterConfig::default();
    let mut state = CharacterState::at(from);
    state.grounded = true;
    let mut buffers = QueryBuffers::new();
    let direction = (to - from).normalize();
    let wanted = (to - from).length();
    let speed = 4.0;
    let seconds = 1.0 / 60.0;

    for _ in 0..((wanted / (speed * seconds)).ceil() as u32 * 2) {
        if (state.position - from).dot(direction) >= wanted {
            break;
        }
        state.velocity.x = direction.x * speed;
        state.velocity.z = direction.z * speed;
        state.velocity.y = (state.velocity.y - 9.81 * seconds).max(-60.0);
        let displacement = state.velocity * seconds;
        move_character(world, &config, &mut state, displacement, &mut buffers);
    }
    state.position
}

#[test]
fn the_level_on_disk_has_every_system_in_it() {
    let scene = showcase();
    assert!(scene.terrain.is_some(), "no terrain in the file");
    assert!(!scene.water.is_empty(), "no water in the file");
    assert!(!scene.spawn_points.is_empty(), "no spawn point in the file");
    assert!(
        !scene.collision_shapes.is_empty(),
        "no authored collision in the file"
    );
    assert!(scene.objects.len() > 20, "{} objects", scene.objects.len());
}

#[test]
fn the_player_starts_somewhere_they_can_stand() {
    // A spawn point inside a rock or under the ground is the most annoying possible bug in a
    // level, and the cheapest one to catch.
    let scene = showcase();
    let spawn = scene.player_spawn();
    let ground = scene.ground_at(spawn.position);
    assert!(
        (spawn.position.y - ground).abs() < 0.5,
        "the spawn is at y {:.2} and the ground there is {ground:.2}",
        spawn.position.y
    );
    assert!(
        !scene.is_submerged(spawn.position),
        "the player starts under water"
    );

    // And nothing solid is standing in it: a character put there and left alone stays there.
    let world = world_of(&scene);
    let settled = walk(
        &world,
        spawn.position + Vec3::new(0.0, 0.1, 0.0),
        spawn.position + Vec3::new(0.0, 0.1, 0.01),
    );
    assert!(
        (settled - spawn.position).length() < 1.5,
        "a character put at the spawn ended up at {settled:?}"
    );
}

#[test]
fn a_character_can_walk_from_the_spawn_towards_the_cliffs() {
    // The plain in front of the level is walkable: no invisible wall between where a player
    // starts and what they are looking at.
    let scene = showcase();
    let world = world_of(&scene);
    let spawn = scene.player_spawn().position;

    let ended = walk(
        &world,
        spawn + Vec3::new(0.0, 0.1, 0.0),
        Vec3::new(0.0, 0.1, -6.0),
    );
    assert!(
        ended.z < -2.0,
        "the character stopped at z {:.2} on the way to the cliffs",
        ended.z
    );
}

#[test]
fn a_character_can_walk_into_the_cave_mouth() {
    // The cave in this level, entered from open ground: the piece placement and the terrain
    // shelf under it have to agree, and the doorstep has to be reachable.
    let scene = showcase();
    let world = world_of(&scene);

    // The mouth faces +Z, so the approach is from in front of it.
    let outside = Vec3::new(-18.0, 1.5, -16.0);
    let ended = walk(&world, outside, Vec3::new(-18.0, 1.5, -23.0));
    assert!(
        ended.z < -20.0,
        "the character stopped at z {:.2} outside the cave",
        ended.z
    );
}

#[test]
fn the_lake_is_water_and_not_a_wall() {
    let scene = showcase();
    let world = world_of(&scene);

    // Straight across the middle of it. Water adds no collision, so nothing stops the walk.
    let ended = walk(
        &world,
        Vec3::new(4.0, 0.2, 26.0),
        Vec3::new(34.0, 0.2, 26.0),
    );
    assert!(
        ended.x > 30.0,
        "the character was stopped at x {:.2} by the lake",
        ended.x
    );

    // And the level agrees that the middle of it is under water.
    let middle = Vec3::new(20.0, 0.0, 26.0);
    let on_the_bed = Vec3::new(middle.x, scene.ground_at(middle) + 0.9, middle.z);
    assert!(
        scene.is_submerged(on_the_bed),
        "standing on the lake bed at {on_the_bed:?} is not under water"
    );
}
